<?php
require_once __DIR__.'/bootstrap/app.php';require_role('SUPER_ADMIN');$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$name=trim($_POST['name']??'');$duration=(int)($_POST['duration']??0);$price=(float)($_POST['price']??-1);if($name===''||$duration<1||$duration>36||$price<0)throw new RuntimeException('Enter a name, duration from 1–36 months, and non-negative price.');db_execute('INSERT INTO MEMBERSHIP_PLAN (PlanName,PlanDetails,Duration,Price,AllowsGymAccess,AllowsClasses,ClassLimitPerCycle) VALUES (?,?,?,?,?,?,?)','ssidiis',[$name,trim($_POST['details']??''),$duration,$price,isset($_POST['gym'])?1:0,isset($_POST['classes'])?1:0,$_POST['class_limit']!==''?(int)$_POST['class_limit']:null]);audit('plan.created','MEMBERSHIP_PLAN',db()->insert_id);set_flash('success','Membership plan created.');redirect('plans.php');}catch(Throwable $e){$errors[]=$e->getMessage();}}
$plans=db_all("SELECT p.*,(SELECT COUNT(*) FROM SUBSCRIPTION s WHERE s.PlanID=p.PlanID AND s.Status='ACTIVE') ActiveMembers FROM MEMBERSHIP_PLAN p ORDER BY p.IsActive DESC,p.Price");$pageTitle='Membership plans';$pageSubtitle='Feature access is enforced by each subscription plan';include ROOT_PATH.'/includes/header.php';?><?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><div class="split-layout"><div class="form-card"><h2 class="section-title">Create plan</h2><form method="post"><?=csrf_field()?><div class="form-group"><label for="name">Plan name</label><input id="name" name="name" required></div><div class="form-group"><label for="details">Details</label><textarea id="details" name="details"></textarea></div><div class="form-grid"><div class="form-group"><label for="duration">Duration (months)</label><input id="duration" type="number" name="duration" min="1" max="36" required></div><div class="form-group"><label for="price">Price (LKR)</label><input id="price" type="number" name="price" min="0" step="0.01" required></div><label class="check-row"><input type="checkbox" name="gym" checked> Gym access</label><label class="check-row"><input type="checkbox" name="classes"> Class access</label><div class="form-group form-full"><label for="class_limit">Class limit per cycle (blank = unlimited)</label><input id="class_limit" type="number" name="class_limit" min="1" max="100"></div></div><div class="form-actions"><button class="btn btn-primary">Create plan</button></div></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th scope="col">Plan</th><th scope="col">Price</th><th scope="col">Features</th><th scope="col">Active</th></tr></thead><tbody><?php foreach($plans as $p):?><tr><td><strong><?=e($p['PlanName'])?></strong><br><small><?=e($p['Duration'])?> month(s)</small></td><td>Rs.<?=number_format((float)$p['Price'],2)?></td><td><?= $p['AllowsGymAccess']?'Gym ':''?><?= $p['AllowsClasses']?'· Classes':''?></td><td><?=$p['ActiveMembers']?> member(s)</td></tr><?php endforeach;?></tbody></table></div></div><?php include ROOT_PATH.'/includes/footer.php';?>
